bgMusic.loop = true;
bgMusic.volume = 0.3;
bgMusic.play().catch(() => {}); // start background music silently if allowed

window.addEventListener('keydown', (e) => {
  keys[e.code] = true;
  if (e.code === 'ArrowUp') {
    if (thrustSound.paused) {
      thrustSound.currentTime = 0;
      thrustSound.play().catch(() => {});
    }
  }
});
window.addEventListener('keyup', (e) => {
  keys[e.code] = false;
  if (e.code === 'ArrowUp') {
    thrustSound.pause();
    thrustSound.currentTime = 0;
  }
});

